import urllib.request,concurrent.futures,json,pathlib,re,hashlib
root=pathlib.Path('intake'); brief=(root/'brief.md').read_text()
urls={
'megadock_readme':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/README.md',
'megadock_license':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/LICENSE',
'pinder_license':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/LICENSE',
'pinder_readme':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/README.md',
'pinder_data_readme':'https://pinderdata.org/2024-02/README.md'}
m=json.loads(re.search(r'"'```json'"\\n(.*?)\\n"'```'"',brief,re.S).group(1))
paths={'index.parquet'}
for c in m['cases']: paths.update([c['apo_receptor_source'],c['apo_ligand_source'],c['reference']])
urls.update({p:'https://pinderdata.org/2024-02/'+p for p in paths})
def fetch(kv):
 k,u=kv
 try:
  req=urllib.request.Request(u,method='HEAD' if k=='index.parquet' else 'GET')
  with urllib.request.urlopen(req,timeout=25) as r: b=r.read(); status=r.status
  item={'url':u,'status':status,'method':req.method,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest() if b else None}
  if k not in paths: item['text']=b.decode(errors='replace')
  elif k"'!='"'index.parquet':
   item['recorded_sha256']=next((h for url,h in re.findall(r'(https://\\S+)\\s*\\|["'^'"\\n]*?"'`([0-9a-f]{64})`'"',brief) if url==u),None)
   item['hash_matches']=item['sha256']==item['recorded_sha256']
   for c in m['cases']:
    for role,ch in [('receptor','R'),('ligand','L')]:
     if c['apo_'+role+'_source']==k:
      out=''.join(line[:21]+ch+line[22:] if line.startswith(('ATOM  ','HETATM','ANISOU','TER   ')) else line for line in b.decode().splitlines(keepends=True)).encode()
      c.setdefault('intake_generated_hash_check',{})[role]={'sha256':hashlib.sha256(out).hexdigest(),'matches':hashlib.sha256(out).hexdigest()==c['historical_prepared_sha256'][role]}
  return k,item
 except Exception as e: return k,{'url':u,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex: evidence=dict(ex.map(fetch,urls.items()))
(root/'source_evidence.json').write_text(json.dumps(evidence,indent=2)+'\\n')
(root/'case_evidence.json').write_text(json.dumps(m,indent=2)+'\\n')
for k,v in evidence.items():
 print(k, json.dumps(v)[:16000] if k not in paths else json.dumps(v))
print('PREPARED',json.dumps([c.get('intake_generated_hash_check') for c in m['cases']]))
PY"

